\subsection{Background}
\subsubsection{Historical Context}
\section{Methodology}
\subsection{Data Collection}
\subsection{Data Analysis}
\section{Results}

% Generate the table of contents
\tableofcontents

% The body of the document follows here

\end{document}
```

